"use strict";
// Reusable finite preparation contract. Does not invent unit strength or combat rules.
window.SourceCommand={create(source){
 const clone=x=>JSON.parse(JSON.stringify(x));
 const initial=(id,profile='operational',staff=10)=>({version:1,id,profile,staff,time:0,revision:0,commands:[],events:[],queue:[],plan:null,sourceHashes:{},stock:{ammunition:'depot',fuel:'depot'},reserve:'none',missions:{M04:{state:'Draft',choice:null}}});
 const ready=s=>!s.plan?'Issue the mission order.':s.time<5+s.staff?'Wait for order receipt and staff preparation.':s.stock.ammunition!=='M04'?'Wait for supplies at the mission supply point.':'';
 function execute(old,c){const s=clone(old);const same=s.commands.find(x=>x.id===c.id);if(same){if(JSON.stringify(same)!==JSON.stringify(c))throw Error('Command ID reused');return s;}if(c.revision!==s.revision)throw Error('Command changed. Reload.');
 if(c.type==='allocate'){if(s.plan||!['standard','priority'].includes(c.plan?.delivery)||!c.sourceHashes?.M04)throw Error('Choose a delivery plan and valid source.');s.plan=clone(c.plan);s.sourceHashes=clone(c.sourceHashes);s.queue=[{at:5,kind:'order'},{at:5+s.staff,kind:'prepared'},{at:s.staff,kind:'dispatch'}];s.missions.M04.state='Order in transit';}
 else if(c.type==='advance'){if(!s.queue.length)throw Error('No next event');s.time=Math.min(...s.queue.map(x=>x.at));const due=s.queue.filter(x=>x.at===s.time);s.queue=s.queue.filter(x=>x.at!==s.time);for(const e of due){if(e.kind==='order')s.missions.M04.state='Preparing';if(e.kind==='prepared')s.missions.M04.state='Prepared';if(e.kind==='dispatch'){const duration=s.plan.delivery==='priority'?20:30;s.transport={depart:s.time,arrival:s.time+duration,status:'transit'};s.stock={ammunition:'transit',fuel:'transit'};s.queue.push({at:s.time+duration,kind:'arrival'});}if(e.kind==='arrival'){s.transport.status='delivered';s.stock={ammunition:'M04',fuel:'M04'};}s.events.push({at:s.time,text:e.kind});}}
 else if(c.type==='commit'){if(s.missions.M04.choice||ready(s))throw Error(ready(s)||'Already committed');s.missions.M04={...s.missions.M04,state:'Committed',choice:'supplied',committedAt:s.time};s.stock={ammunition:'issued',fuel:'issued'};}else throw Error('Unknown command');s.commands.push(clone(c));s.revision++;return s;}
 function restore(raw){if(raw.version!==1||![10,20].includes(raw.staff))throw Error('Invalid source operation');let s=initial(raw.id,raw.profile,raw.staff);for(const c of raw.commands)s=execute(s,c);return s;}
 function variant(s,id,d){if(id!=='M04'||!s.missions.M04.choice||d.id!==source.id)throw Error('Commit this source mission first');const out=clone(d);out.id=s.id+':'+d.id;delete out.parentMapLocation;out.parentCampaign={...out.parentCampaign,commandSnapshotId:s.id};out.campaignAssignment={...out.campaignAssignment,situationId:out.id};out.briefing='AUTHORED PREPARATION. Original forces and deployment restrictions retained. Supplies issued at '+NormandyCommand.clock(s.time)+'. '+out.briefing;return out;}
 return {initial,execute,restore,ready,variant,clock:NormandyCommand.clock};
}};
